/**
 * One-off D5 receipt: capture the FTS cells and logical hash the *current*
 * SQLite writer produces for the deterministic 120-workflow fixture.
 *
 * Run before any change to `sqlite.ts`:
 *
 *   node --import tsx pipeline/export/capture-sqlite-fts-baseline.mjs > pipeline/__fixtures__/sqlite-fts-baseline.json
 *
 * The output is generated by the real `writeSqliteRelease` path and a real
 * `SELECT ... FROM workflow_search ORDER BY workflow_id`; it is never
 * hand-authored and CI never regenerates it.
 */
import { mkdtempSync, rmSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { makeEntry } from '../__fixtures__/make-entry.ts';
import { releaseForEntries } from '../__fixtures__/scan-provenance-cases.ts';
import { buildPublicProjection } from './public-projection.ts';
import { writeSqliteRelease } from './sqlite.ts';

const entries = Array.from({ length: 120 }, (_, index) => makeEntry({
  id: `perf-${index}`,
  tags: [`tag-${(index * 3) % 400}`, `tag-${(index * 3 + 1) % 400}`, `tag-${(index * 3 + 2) % 400}`],
  structure: {
    integrations: [
      `integration-${(index * 3) % 400}`,
      `integration-${(index * 3 + 1) % 400}`,
      `integration-${(index * 3 + 2) % 400}`,
    ],
    trigger: `trigger-${index % 120}`,
  },
}));
const projection = buildPublicProjection(entries, { release: releaseForEntries(entries) });
const dir = mkdtempSync(path.join(os.tmpdir(), 'd5-baseline-'));
const database = path.join(dir, 'release.sqlite');
try {
  const info = writeSqliteRelease(projection, database);
  const db = new DatabaseSync(database);
  const rows = db.prepare(`SELECT workflow_id, tags, integrations, triggers FROM workflow_search
    ORDER BY workflow_id`).all();
  db.close();
  process.stdout.write(`${JSON.stringify({ logicalSha256: info.logicalSha256, workflowSearch: rows }, null, 2)}\n`);
} finally {
  rmSync(dir, { recursive: true, force: true });
}
